-- Incidentes ficticios para la base nexo_dev_bcp. Los 300 cargados son de PRODUCCIÓN; la columna
-- ambiente admite también QA, para los incidentes que crea el agente (SPEC 09).
-- Se ejecuta DESPUÉS de db/nexo_dev_bcp_postgresql.sql y de db/nexo_dev_bcp_migracion.sql.
-- Es repetible: borra y recrea la tabla jira_incidentes en cada ejecución.
--
-- Contenido: 300 incidentes, 2 por cada servicio del catálogo portal_apis (150 servicios),
-- siempre de dos tipos distintos. Todos los datos son inventados: no representan incidentes reales.
-- Los tipos de incidente siguen los ejemplos del README (error HTTP 500, alto consumo de memoria
-- y de CPU en bases de datos) y suman fallas habituales de operación.
--
-- Las fechas son SIMULADAS y relativas al momento de la carga: creado_en queda entre 0 y 89 días
-- atrás y resuelto_en, cuando existe, es posterior a creado_en. Pasados 90 días hay que recargar.
-- Los estados son los mismos de jira_tickets: Registrado, En Procesado y Terminado. Solo los
-- incidentes Terminado tienen causa raíz definitiva, solución y fecha de resolución.
-- grupo_resolutor usa los mismos 6 grupos de jira_tickets.
-- Datos generados de forma determinista a partir del catálogo.

DROP TABLE IF EXISTS nexo_dev_bcp.jira_incidentes CASCADE;

CREATE TABLE nexo_dev_bcp.jira_incidentes (
    codigo_incidente  TEXT PRIMARY KEY,
    codigo_aplicacion TEXT NOT NULL REFERENCES nexo_dev_bcp.cvt (codigo_aplicacion),
    api_id            INTEGER NOT NULL REFERENCES nexo_dev_bcp.portal_apis (api_id),
    ambiente          TEXT NOT NULL DEFAULT 'Producción' CHECK (ambiente IN ('QA', 'Producción')),
    severidad         TEXT NOT NULL CHECK (severidad IN ('Crítica', 'Alta', 'Media', 'Baja')),
    tipo_incidente    TEXT NOT NULL CHECK (tipo_incidente IN (
        'error_http_5xx', 'latencia_timeout', 'memoria_bd', 'cpu_bd', 'conexiones_bd',
        'certificado_vencido', 'autenticacion', 'despliegue_fallido', 'contrato_incompatible',
        'integracion_mainframe', 'monitoreo'
    )),
    titulo            TEXT NOT NULL,
    descripcion       TEXT NOT NULL,
    evidencias        TEXT,
    causa_raiz        TEXT,
    solucion          TEXT,
    grupo_resolutor   TEXT NOT NULL CHECK (grupo_resolutor IN (
        'Seguridad', 'Control de Accesos', 'AgileOPS', 'Base de Datos',
        'Soporte ITSM', 'Soporte Mainframe'
    )),
    estado            TEXT NOT NULL DEFAULT 'Registrado'
        CHECK (estado IN ('Registrado', 'En Procesado', 'Terminado')),
    url               TEXT,
    creado_en         TIMESTAMPTZ NOT NULL,
    resuelto_en       TIMESTAMPTZ,
    busqueda          TSVECTOR GENERATED ALWAYS AS (
        to_tsvector('spanish',
            coalesce(titulo, '') || ' ' || coalesce(descripcion, '') || ' ' ||
            coalesce(causa_raiz, '') || ' ' || coalesce(solucion, ''))
    ) STORED,
    CHECK ((estado = 'Terminado') = (resuelto_en IS NOT NULL)),
    CHECK (resuelto_en IS NULL OR resuelto_en >= creado_en),
    CHECK (estado <> 'Terminado' OR (causa_raiz IS NOT NULL AND solucion IS NOT NULL)),
    CHECK (solucion IS NULL OR estado = 'Terminado')
);

CREATE INDEX idx_jira_incidentes_api ON nexo_dev_bcp.jira_incidentes (api_id);
CREATE INDEX idx_jira_incidentes_aplicacion ON nexo_dev_bcp.jira_incidentes (codigo_aplicacion);
CREATE INDEX idx_jira_incidentes_busqueda ON nexo_dev_bcp.jira_incidentes USING GIN (busqueda);

INSERT INTO nexo_dev_bcp.jira_incidentes
    (codigo_incidente, codigo_aplicacion, api_id, severidad, tipo_incidente, titulo, descripcion,
     evidencias, causa_raiz, solucion, grupo_resolutor, estado, url, creado_en, resuelto_en) VALUES
    ('INC-100001', 'YAPE', 1, 'Media', 'error_http_5xx', 'Error HTTP 500 en Pagos de billetera', 'Los consumidores de Pagos de billetera (GET /v1/pagos/{id}) reciben HTTP 500 de forma intermitente en producción. Se registran 89 errores en 15 minutos y el 20.6% de las solicitudes falla.', 'Unhandled exception en el controlador del servicio | GET /v1/pagos/{id} | HTTP 500 | 89 errores en 15 min', 'Un dato con formato inesperado rompía la serialización de la respuesta.', 'Se validan los campos opcionales antes de armar la respuesta y se devuelve 404 cuando el recurso no existe. Se despliega el parche y se monitorea durante 60 minutos.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100001', now() - make_interval(mins => 116669), now() - make_interval(mins => 116415)),
    ('INC-100002', 'YAPE', 1, 'Alta', 'certificado_vencido', 'Certificado TLS vencido en Pagos de billetera', 'Las llamadas a Pagos de billetera (GET /v1/pagos/{id}) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', 'PKIX path validation failed: certificate expired | 19.6% de solicitudes fallidas', 'El certificado no se renovó a tiempo y no había alerta de vencimiento.', 'Se renueva el certificado y se agrega una alerta 30 días antes del vencimiento.', 'Seguridad', 'Terminado', 'https://jira.demo.example/browse/INC-100002', now() - make_interval(mins => 128956), now() - make_interval(mins => 128887)),
    ('INC-100003', 'YAPE', 2, 'Media', 'latencia_timeout', 'Alta latencia y timeouts en Pagos de billetera', 'El servicio Pagos de billetera (POST /v1/pagos) de YAPE responde con un percentil 95 de 3353 ms (umbral de 800 ms) y el 14.7% de las solicitudes termina en timeout.', 'Latencia p95 de 3353 ms sostenida durante 45 min | POST /v1/pagos', 'Una dependencia interna respondía lento y no había un tiempo máximo configurado.', 'Se define un tiempo máximo de 3 s con reintentos y espera exponencial hacia la dependencia.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100003', now() - make_interval(mins => 95922), now() - make_interval(mins => 94947)),
    ('INC-100004', 'YAPE', 2, 'Alta', 'certificado_vencido', 'Certificado TLS vencido en Pagos de billetera', 'Las llamadas a Pagos de billetera (POST /v1/pagos) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', NULL, 'El certificado no se renovó a tiempo y no había alerta de vencimiento.', 'Se renueva el certificado y se agrega una alerta 30 días antes del vencimiento.', 'Seguridad', 'Terminado', 'https://jira.demo.example/browse/INC-100004', now() - make_interval(mins => 67952), now() - make_interval(mins => 67796)),
    ('INC-100005', 'MBBK', 3, 'Alta', 'error_http_5xx', 'Error HTTP 500 en Saldos de cuentas', 'El servicio Saldos de cuentas (GET /v1/saldos/{cuentaId}) de MBBK responde HTTP 500 en producción. El 31.1% de las solicitudes de los últimos 120 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'NullPointerException en el mapeador de respuesta | GET /v1/saldos/{cuentaId} | HTTP 500 | 31.1% de solicitudes', NULL, NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100005', now() - make_interval(mins => 80565), NULL),
    ('INC-100006', 'MBBK', 3, 'Media', 'contrato_incompatible', 'Cambio de contrato rompe a los consumidores de Saldos de cuentas', 'Un cambio en el contrato de Saldos de cuentas (GET /v1/saldos/{cuentaId}) provoca HTTP 400 en los consumidores de MBBK. El 13.2% de las solicitudes es rechazado por validación.', 'Contrato OpenAPI v1.698 no coincide con la versión que usa el canal | GET /v1/saldos/{cuentaId}', NULL, NULL, 'AgileOPS', 'Registrado', 'https://jira.demo.example/browse/INC-100006', now() - make_interval(mins => 25453), NULL),
    ('INC-100007', 'TTIB', 4, 'Media', 'latencia_timeout', 'Alta latencia y timeouts en Transferencias interbancarias', 'El servicio Transferencias interbancarias (GET /v1/transferencias/{id}) de TTIB responde con un percentil 95 de 5391 ms (umbral de 800 ms) y el 10.4% de las solicitudes termina en timeout.', 'p95=5391 ms | timeouts=205 en 120 min | GET /v1/transferencias/{id}', NULL, NULL, 'AgileOPS', 'Registrado', 'https://jira.demo.example/browse/INC-100007', now() - make_interval(mins => 114306), NULL),
    ('INC-100008', 'TTIB', 4, 'Crítica', 'conexiones_bd', 'Pool de conexiones agotado en Transferencias interbancarias', 'El servicio Transferencias interbancarias (GET /v1/transferencias/{id}) de TTIB devuelve errores porque todas las conexiones a la base de datos están ocupadas. El 36.4% de las solicitudes falla en horas pico.', 'Connection is not available, request timed out after 30000ms | GET /v1/transferencias/{id}', 'Conexiones que no se liberaban por un error en el manejo de transacciones.', 'Se amplía el pool de conexiones y se define un tiempo máximo de uso por conexión.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100008', now() - make_interval(mins => 127115), now() - make_interval(mins => 127079)),
    ('INC-100009', 'TTIB', 5, 'Media', 'contrato_incompatible', 'Cambio de contrato rompe a los consumidores de Transferencias interbancarias', 'Un cambio en el contrato de Transferencias interbancarias (POST /v1/transferencias) provoca HTTP 400 en los consumidores de TTIB. El 20.0% de las solicitudes es rechazado por validación.', 'HTTP 400: campo requerido ausente | POST /v1/transferencias | 20.0% de solicitudes', 'Se agregó un campo obligatorio sin versionar el contrato.', 'Se hace opcional el campo nuevo, se publica el contrato versionado y se coordina la migración de los consumidores.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100009', now() - make_interval(mins => 54523), now() - make_interval(mins => 53660)),
    ('INC-100010', 'TTIB', 5, 'Crítica', 'error_http_5xx', 'Error HTTP 500 en Transferencias interbancarias', 'El servicio Transferencias interbancarias (POST /v1/transferencias) de TTIB responde HTTP 500 en producción. El 8.0% de las solicitudes de los últimos 15 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'HTTP 500 sostenido en POST /v1/transferencias | pico de 774 errores por minuto', 'Un dato con formato inesperado rompía la serialización de la respuesta.', 'Se agrega el manejo de la excepción y una respuesta de error controlada. Se incorpora una prueba que reproduce el caso.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100010', now() - make_interval(mins => 55522), now() - make_interval(mins => 55488)),
    ('INC-100011', 'YAPE', 6, 'Alta', 'error_http_5xx', 'Error HTTP 500 en Pagos de billetera · Web (perfil-02)', 'El servicio Pagos de billetera · Web (perfil-02) (GET /perfil-02/v1/pagos/{id}) de YAPE responde HTTP 500 en producción. El 37.6% de las solicitudes de los últimos 45 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'NullPointerException en el mapeador de respuesta | GET /perfil-02/v1/pagos/{id} | HTTP 500 | 37.6% de solicitudes', NULL, NULL, 'AgileOPS', 'Registrado', 'https://jira.demo.example/browse/INC-100011', now() - make_interval(mins => 46420), NULL),
    ('INC-100012', 'YAPE', 6, 'Alta', 'contrato_incompatible', 'Cambio de contrato rompe a los consumidores de Pagos de billetera · Web (perfil-02)', 'Un cambio en el contrato de Pagos de billetera · Web (perfil-02) (GET /perfil-02/v1/pagos/{id}) provoca HTTP 400 en los consumidores de YAPE. El 21.1% de las solicitudes es rechazado por validación.', 'Contrato OpenAPI v1.644 no coincide con la versión que usa el canal | GET /perfil-02/v1/pagos/{id}', 'Se agregó un campo obligatorio sin versionar el contrato.', 'Se hace opcional el campo nuevo, se publica el contrato versionado y se coordina la migración de los consumidores.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100012', now() - make_interval(mins => 36998), now() - make_interval(mins => 36836)),
    ('INC-100013', 'YAPE', 7, 'Alta', 'error_http_5xx', 'Error HTTP 500 en Pagos de billetera · Web (perfil-02)', 'El servicio Pagos de billetera · Web (perfil-02) (POST /perfil-02/v1/pagos) de YAPE responde HTTP 500 en producción. El 22.9% de las solicitudes de los últimos 30 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'HTTP 500 sostenido en POST /perfil-02/v1/pagos | pico de 108 errores por minuto', 'Hipótesis: una excepción no controlada en el controlador tras el último cambio de código.', NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100013', now() - make_interval(mins => 26976), NULL),
    ('INC-100014', 'YAPE', 7, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Pagos de billetera · Web (perfil-02)', 'El servicio Pagos de billetera · Web (perfil-02) (POST /perfil-02/v1/pagos) falla al invocar la transacción del mainframe. El 21.1% de las solicitudes termina en error o timeout.', NULL, 'Una ventana de mantenimiento del mainframe no se comunicó al equipo.', 'Se reprograma el proceso batch fuera del horario de atención y se limita su concurrencia.', 'Soporte Mainframe', 'Terminado', 'https://jira.demo.example/browse/INC-100014', now() - make_interval(mins => 74078), now() - make_interval(mins => 73512)),
    ('INC-100015', 'YAPE', 8, 'Baja', 'latencia_timeout', 'Alta latencia y timeouts en Pagos de billetera · Móvil (perfil-03)', 'El servicio Pagos de billetera · Móvil (perfil-03) (GET /perfil-03/v1/pagos/{id}) de YAPE responde con un percentil 95 de 1524 ms (umbral de 800 ms) y el 37.8% de las solicitudes termina en timeout.', 'p95=1524 ms | timeouts=630 en 30 min | GET /perfil-03/v1/pagos/{id}', 'Hipótesis: el pool de hilos del servicio estaba saturado por reintentos de los consumidores.', NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100015', now() - make_interval(mins => 781), NULL),
    ('INC-100016', 'YAPE', 8, 'Crítica', 'conexiones_bd', 'Pool de conexiones agotado en Pagos de billetera · Móvil (perfil-03)', 'El servicio Pagos de billetera · Móvil (perfil-03) (GET /perfil-03/v1/pagos/{id}) de YAPE devuelve errores porque todas las conexiones a la base de datos están ocupadas. El 36.6% de las solicitudes falla en horas pico.', 'Connection is not available, request timed out after 30000ms | GET /perfil-03/v1/pagos/{id}', NULL, NULL, 'Base de Datos', 'En Procesado', 'https://jira.demo.example/browse/INC-100016', now() - make_interval(mins => 91390), NULL),
    ('INC-100017', 'YAPE', 9, 'Alta', 'despliegue_fallido', 'Servicio Pagos de billetera · Móvil (perfil-03) caído tras un despliegue', 'Tras el pase a producción, Pagos de billetera · Móvil (perfil-03) (POST /perfil-03/v1/pagos) de YAPE no responde. El servicio reinicia de forma continua y los consumidores reciben errores.', NULL, 'El pase incluyó una variable de configuración que no existía en producción.', 'Se aplica el ajuste de esquema pendiente y se vuelve a desplegar la versión.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100017', now() - make_interval(mins => 17707), now() - make_interval(mins => 17512)),
    ('INC-100018', 'YAPE', 9, 'Alta', 'cpu_bd', 'Alto consumo de CPU en la base de datos de Pagos de billetera · Móvil (perfil-03)', 'La base de datos de Pagos de billetera · Móvil (perfil-03) (YAPE) sostiene 13.4% de CPU durante 45 minutos. Las solicitudes a POST /perfil-03/v1/pagos aumentan su tiempo de respuesta.', 'CPU 13.4% durante 45 min | consulta de 169 s sin índice', 'El servicio ejecutaba miles de consultas pequeñas por solicitud.', 'Se crea un índice compuesto sobre las columnas de filtro.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100018', now() - make_interval(mins => 52810), now() - make_interval(mins => 52601)),
    ('INC-100019', 'YAPE', 10, 'Baja', 'monitoreo', 'Alertas no emitidas para Pagos de billetera · Conciliación (perfil-04)', 'El servicio Pagos de billetera · Conciliación (perfil-04) (GET /perfil-04/v1/pagos/{id}) tuvo errores visibles en los logs durante 60 minutos, pero no se emitió ninguna alerta al equipo de soporte.', 'Sin eventos de alerta durante 60 min con errores 5xx en los logs | GET /perfil-04/v1/pagos/{id}', NULL, NULL, 'Soporte ITSM', 'En Procesado', 'https://jira.demo.example/browse/INC-100019', now() - make_interval(mins => 14422), NULL),
    ('INC-100020', 'YAPE', 10, 'Alta', 'cpu_bd', 'Alto consumo de CPU en la base de datos de Pagos de billetera · Conciliación (perfil-04)', 'La base de datos de Pagos de billetera · Conciliación (perfil-04) (YAPE) sostiene 2.2% de CPU durante 30 minutos. Las solicitudes a GET /perfil-04/v1/pagos/{id} aumentan su tiempo de respuesta.', 'CPU 2.2% durante 30 min | consulta de 514 s sin índice', 'El servicio ejecutaba miles de consultas pequeñas por solicitud.', 'Se actualizan las estadísticas y se programa el mantenimiento automático.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100020', now() - make_interval(mins => 92072), now() - make_interval(mins => 92024)),
    ('INC-100021', 'YAPE', 11, 'Media', 'autenticacion', 'Errores 401 y 403 en Pagos de billetera · Conciliación (perfil-04)', 'Los consumidores de Pagos de billetera · Conciliación (perfil-04) (POST /perfil-04/v1/pagos) reciben HTTP 401 y 403 en producción. El 21.0% de las solicitudes es rechazado por autenticación.', 'HTTP 403 perfil de consumo sin permiso | POST /perfil-04/v1/pagos | 64 rechazos en 30 min', 'Los tokens se validaban con una diferencia de relojes entre servidores.', 'Se agrega un margen de tolerancia de 30 segundos en la validación de expiración del token.', 'Control de Accesos', 'Terminado', 'https://jira.demo.example/browse/INC-100021', now() - make_interval(mins => 70229), now() - make_interval(mins => 68828)),
    ('INC-100022', 'YAPE', 11, 'Media', 'conexiones_bd', 'Pool de conexiones agotado en Pagos de billetera · Conciliación (perfil-04)', 'El servicio Pagos de billetera · Conciliación (perfil-04) (POST /perfil-04/v1/pagos) de YAPE devuelve errores porque todas las conexiones a la base de datos están ocupadas. El 11.0% de las solicitudes falla en horas pico.', 'Connection is not available, request timed out after 30000ms | POST /perfil-04/v1/pagos', 'El pool de conexiones era demasiado pequeño para el volumen de la hora pico.', 'Se amplía el pool de conexiones y se define un tiempo máximo de uso por conexión.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100022', now() - make_interval(mins => 70233), now() - make_interval(mins => 69052)),
    ('INC-100023', 'YAPE', 12, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Pagos de billetera · Backoffice (perfil-05)', 'El servicio Pagos de billetera · Backoffice (perfil-05) (GET /perfil-05/v1/pagos/{id}) falla al invocar la transacción del mainframe. El 5.3% de las solicitudes termina en error o timeout.', 'Respuesta vacía del mainframe | 744 solicitudes afectadas en 45 min', NULL, NULL, 'Soporte Mainframe', 'Registrado', 'https://jira.demo.example/browse/INC-100023', now() - make_interval(mins => 30134), NULL),
    ('INC-100024', 'YAPE', 12, 'Baja', 'latencia_timeout', 'Alta latencia y timeouts en Pagos de billetera · Backoffice (perfil-05)', 'El servicio Pagos de billetera · Backoffice (perfil-05) (GET /perfil-05/v1/pagos/{id}) de YAPE responde con un percentil 95 de 5868 ms (umbral de 800 ms) y el 30.5% de las solicitudes termina en timeout.', 'p95=5868 ms | timeouts=876 en 90 min | GET /perfil-05/v1/pagos/{id}', 'Consultas sin índice a la base de datos aumentaban el tiempo de respuesta.', 'Se limita la tasa de reintentos y se amplía el pool de hilos del servicio.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100024', now() - make_interval(mins => 98203), now() - make_interval(mins => 96886)),
    ('INC-100025', 'YAPE', 13, 'Alta', 'autenticacion', 'Errores 401 y 403 en Pagos de billetera · Backoffice (perfil-05)', 'Los consumidores de Pagos de billetera · Backoffice (perfil-05) (POST /perfil-05/v1/pagos) reciben HTTP 401 y 403 en producción. El 7.5% de las solicitudes es rechazado por autenticación.', 'HTTP 401 invalid_token | POST /perfil-05/v1/pagos | 7.5% de solicitudes', NULL, NULL, 'Control de Accesos', 'En Procesado', 'https://jira.demo.example/browse/INC-100025', now() - make_interval(mins => 1278), NULL),
    ('INC-100026', 'YAPE', 13, 'Alta', 'memoria_bd', 'Alto consumo de memoria en la base de datos de Pagos de billetera · Backoffice (perfil-05)', 'La base de datos que soporta Pagos de billetera · Backoffice (perfil-05) (YAPE) llega al 5.6% de memoria. El servicio (POST /perfil-05/v1/pagos) se degrada y podría fallar por falta de recursos si continúa.', 'Memoria 5.6% durante 60 min | 99 conexiones activas de 500', 'Reportes simultáneos creaban tablas temporales grandes.', 'Se reescribe la consulta con filtros por fecha y paginación.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100026', now() - make_interval(mins => 35696), now() - make_interval(mins => 35498)),
    ('INC-100027', 'YAPE', 14, 'Alta', 'contrato_incompatible', 'Cambio de contrato rompe a los consumidores de Pagos de billetera · Monitoreo (perfil-06)', 'Un cambio en el contrato de Pagos de billetera · Monitoreo (perfil-06) (GET /perfil-06/v1/pagos/{id}) provoca HTTP 400 en los consumidores de YAPE. El 36.5% de las solicitudes es rechazado por validación.', 'HTTP 400: campo requerido ausente | GET /perfil-06/v1/pagos/{id} | 36.5% de solicitudes', 'Hipótesis: se agregó un campo obligatorio sin versionar el contrato.', NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100027', now() - make_interval(mins => 93660), NULL),
    ('INC-100028', 'YAPE', 14, 'Media', 'cpu_bd', 'Alto consumo de CPU en la base de datos de Pagos de billetera · Monitoreo (perfil-06)', 'La base de datos de Pagos de billetera · Monitoreo (perfil-06) (YAPE) sostiene 3.7% de CPU durante 30 minutos. Las solicitudes a GET /perfil-06/v1/pagos/{id} aumentan su tiempo de respuesta.', 'Seq Scan sobre tabla grande | CPU 3.7% | 205 consultas por segundo', 'El servicio ejecutaba miles de consultas pequeñas por solicitud.', 'Se actualizan las estadísticas y se programa el mantenimiento automático.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100028', now() - make_interval(mins => 32305), now() - make_interval(mins => 31134)),
    ('INC-100029', 'YAPE', 15, 'Baja', 'monitoreo', 'Alertas no emitidas para Pagos de billetera · Monitoreo (perfil-06)', 'El servicio Pagos de billetera · Monitoreo (perfil-06) (POST /perfil-06/v1/pagos) tuvo errores visibles en los logs durante 15 minutos, pero no se emitió ninguna alerta al equipo de soporte.', 'Sin eventos de alerta durante 15 min con errores 5xx en los logs | POST /perfil-06/v1/pagos', NULL, NULL, 'Soporte ITSM', 'Registrado', 'https://jira.demo.example/browse/INC-100029', now() - make_interval(mins => 103403), NULL),
    ('INC-100030', 'YAPE', 15, 'Media', 'error_http_5xx', 'Error HTTP 500 en Pagos de billetera · Monitoreo (perfil-06)', 'Los consumidores de Pagos de billetera · Monitoreo (perfil-06) (POST /perfil-06/v1/pagos) reciben HTTP 500 de forma intermitente en producción. Se registran 240 errores en 90 minutos y el 20.7% de las solicitudes falla.', 'HTTP 500 sostenido en POST /perfil-06/v1/pagos | pico de 240 errores por minuto', 'Una excepción no controlada en el controlador tras el último cambio de código.', 'Se corrige la serialización y se agrega validación de formato en la entrada del servicio.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100030', now() - make_interval(mins => 48349), now() - make_interval(mins => 47242)),
    ('INC-100031', 'YAPE', 16, 'Alta', 'integracion_mainframe', 'Fallas de integración con el mainframe en Pagos de billetera · Integración (perfil-07)', 'El servicio Pagos de billetera · Integración (perfil-07) (GET /perfil-07/v1/pagos/{id}) falla al invocar la transacción del mainframe. El 31.1% de las solicitudes termina en error o timeout.', 'Timeout al invocar la transacción del mainframe tras 377 s | GET /perfil-07/v1/pagos/{id}', 'La cola de transacciones del mainframe estaba saturada por un proceso batch.', 'Se coordina el calendario de mantenimientos y se agrega un mensaje de contingencia en el servicio.', 'Soporte Mainframe', 'Terminado', 'https://jira.demo.example/browse/INC-100031', now() - make_interval(mins => 117103), now() - make_interval(mins => 116864)),
    ('INC-100032', 'YAPE', 16, 'Media', 'monitoreo', 'Alertas no emitidas para Pagos de billetera · Integración (perfil-07)', 'El servicio Pagos de billetera · Integración (perfil-07) (GET /perfil-07/v1/pagos/{id}) tuvo errores visibles en los logs durante 90 minutos, pero no se emitió ninguna alerta al equipo de soporte.', 'Sin eventos de alerta durante 90 min con errores 5xx en los logs | GET /perfil-07/v1/pagos/{id}', NULL, NULL, 'Soporte ITSM', 'Registrado', 'https://jira.demo.example/browse/INC-100032', now() - make_interval(mins => 83716), NULL),
    ('INC-100033', 'YAPE', 17, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Pagos de billetera · Integración (perfil-07)', 'El servicio Pagos de billetera · Integración (perfil-07) (POST /perfil-07/v1/pagos) falla al invocar la transacción del mainframe. El 30.0% de las solicitudes termina en error o timeout.', 'Respuesta vacía del mainframe | 97 solicitudes afectadas en 20 min', NULL, NULL, 'Soporte Mainframe', 'Registrado', 'https://jira.demo.example/browse/INC-100033', now() - make_interval(mins => 69755), NULL),
    ('INC-100034', 'YAPE', 17, 'Media', 'latencia_timeout', 'Alta latencia y timeouts en Pagos de billetera · Integración (perfil-07)', 'El servicio Pagos de billetera · Integración (perfil-07) (POST /perfil-07/v1/pagos) de YAPE responde con un percentil 95 de 2473 ms (umbral de 800 ms) y el 13.7% de las solicitudes termina en timeout.', 'p95=2473 ms | timeouts=732 en 60 min | POST /perfil-07/v1/pagos', NULL, NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100034', now() - make_interval(mins => 13432), NULL),
    ('INC-100035', 'YAPE', 18, 'Alta', 'error_http_5xx', 'Error HTTP 500 en Pagos de billetera · Regresión (perfil-08)', 'Los consumidores de Pagos de billetera · Regresión (perfil-08) (GET /perfil-08/v1/pagos/{id}) reciben HTTP 500 de forma intermitente en producción. Se registran 118 errores en 120 minutos y el 34.7% de las solicitudes falla.', 'Unhandled exception en el controlador del servicio | GET /perfil-08/v1/pagos/{id} | HTTP 500 | 118 errores en 120 min', 'Un campo opcional llegaba nulo y no se validaba antes de armar la respuesta.', 'Se validan los campos opcionales antes de armar la respuesta y se devuelve 404 cuando el recurso no existe. Se despliega el parche y se monitorea durante 60 minutos.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100035', now() - make_interval(mins => 128122), now() - make_interval(mins => 127992)),
    ('INC-100036', 'YAPE', 18, 'Alta', 'despliegue_fallido', 'Servicio Pagos de billetera · Regresión (perfil-08) caído tras un despliegue', 'Tras el pase a producción, Pagos de billetera · Regresión (perfil-08) (GET /perfil-08/v1/pagos/{id}) de YAPE no responde. El servicio reinicia de forma continua y los consumidores reciben errores.', 'Pod en CrashLoopBackOff tras el pase | versión 2.710.344', 'El pase incluyó una variable de configuración que no existía en producción.', 'Se revierte a la versión anterior y se corrige la configuración en el pipeline de despliegue.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100036', now() - make_interval(mins => 48832), now() - make_interval(mins => 48702)),
    ('INC-100037', 'YAPE', 19, 'Media', 'cpu_bd', 'Alto consumo de CPU en la base de datos de Pagos de billetera · Regresión (perfil-08)', 'La base de datos de Pagos de billetera · Regresión (perfil-08) (YAPE) sostiene 4.4% de CPU durante 60 minutos. Las solicitudes a POST /perfil-08/v1/pagos aumentan su tiempo de respuesta.', 'Seq Scan sobre tabla grande | CPU 4.4% | 874 consultas por segundo', 'Estadísticas desactualizadas cambiaron el plan de ejecución.', 'Se crea un índice compuesto sobre las columnas de filtro.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100037', now() - make_interval(mins => 116418), now() - make_interval(mins => 115650)),
    ('INC-100038', 'YAPE', 19, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Pagos de billetera · Regresión (perfil-08)', 'El servicio Pagos de billetera · Regresión (perfil-08) (POST /perfil-08/v1/pagos) falla al invocar la transacción del mainframe. El 32.5% de las solicitudes termina en error o timeout.', 'Timeout al invocar la transacción del mainframe tras 668 s | POST /perfil-08/v1/pagos', 'Una ventana de mantenimiento del mainframe no se comunicó al equipo.', 'Se reprograma el proceso batch fuera del horario de atención y se limita su concurrencia.', 'Soporte Mainframe', 'Terminado', 'https://jira.demo.example/browse/INC-100038', now() - make_interval(mins => 80109), now() - make_interval(mins => 78970)),
    ('INC-100039', 'YAPE', 20, 'Crítica', 'despliegue_fallido', 'Servicio Pagos de billetera · Contingencia (perfil-09) caído tras un despliegue', 'Tras el pase a producción, Pagos de billetera · Contingencia (perfil-09) (GET /perfil-09/v1/pagos/{id}) de YAPE no responde. El servicio reinicia de forma continua y los consumidores reciben errores.', 'Pod en CrashLoopBackOff tras el pase | versión 2.485.367', 'La nueva versión era incompatible con el esquema vigente de la base de datos.', 'Se aplica el ajuste de esquema pendiente y se vuelve a desplegar la versión.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100039', now() - make_interval(mins => 123261), now() - make_interval(mins => 123164)),
    ('INC-100040', 'YAPE', 20, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Pagos de billetera · Contingencia (perfil-09)', 'El servicio Pagos de billetera · Contingencia (perfil-09) (GET /perfil-09/v1/pagos/{id}) falla al invocar la transacción del mainframe. El 15.0% de las solicitudes termina en error o timeout.', NULL, 'La cola de transacciones del mainframe estaba saturada por un proceso batch.', 'Se reprograma el proceso batch fuera del horario de atención y se limita su concurrencia.', 'Soporte Mainframe', 'Terminado', 'https://jira.demo.example/browse/INC-100040', now() - make_interval(mins => 30401), now() - make_interval(mins => 29604)),
    ('INC-100041', 'YAPE', 21, 'Alta', 'latencia_timeout', 'Alta latencia y timeouts en Pagos de billetera · Contingencia (perfil-09)', 'El servicio Pagos de billetera · Contingencia (perfil-09) (POST /perfil-09/v1/pagos) de YAPE responde con un percentil 95 de 3102 ms (umbral de 800 ms) y el 27.6% de las solicitudes termina en timeout.', 'p95=3102 ms | timeouts=198 en 120 min | POST /perfil-09/v1/pagos', 'Hipótesis: el pool de hilos del servicio estaba saturado por reintentos de los consumidores.', NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100041', now() - make_interval(mins => 78240), NULL),
    ('INC-100042', 'YAPE', 21, 'Alta', 'certificado_vencido', 'Certificado TLS vencido en Pagos de billetera · Contingencia (perfil-09)', 'Las llamadas a Pagos de billetera · Contingencia (perfil-09) (POST /perfil-09/v1/pagos) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', 'PKIX path validation failed: certificate expired | 16.2% de solicitudes fallidas', 'El certificado no se renovó a tiempo y no había alerta de vencimiento.', 'Se renueva el certificado y se agrega una alerta 30 días antes del vencimiento.', 'Seguridad', 'Terminado', 'https://jira.demo.example/browse/INC-100042', now() - make_interval(mins => 69782), now() - make_interval(mins => 69569)),
    ('INC-100043', 'YAPE', 22, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Pagos de billetera · Operaciones (perfil-10)', 'El servicio Pagos de billetera · Operaciones (perfil-10) (GET /perfil-10/v1/pagos/{id}) falla al invocar la transacción del mainframe. El 27.4% de las solicitudes termina en error o timeout.', 'Timeout al invocar la transacción del mainframe tras 436 s | GET /perfil-10/v1/pagos/{id}', 'Una ventana de mantenimiento del mainframe no se comunicó al equipo.', 'Se coordina el calendario de mantenimientos y se agrega un mensaje de contingencia en el servicio.', 'Soporte Mainframe', 'Terminado', 'https://jira.demo.example/browse/INC-100043', now() - make_interval(mins => 89812), now() - make_interval(mins => 88818)),
    ('INC-100044', 'YAPE', 22, 'Crítica', 'cpu_bd', 'Alto consumo de CPU en la base de datos de Pagos de billetera · Operaciones (perfil-10)', 'La base de datos de Pagos de billetera · Operaciones (perfil-10) (YAPE) sostiene 37.0% de CPU durante 120 minutos. Las solicitudes a GET /perfil-10/v1/pagos/{id} aumentan su tiempo de respuesta.', 'CPU 37.0% durante 120 min | consulta de 201 s sin índice', 'Hipótesis: una consulta frecuente sin índice recorría la tabla completa.', NULL, 'Base de Datos', 'En Procesado', 'https://jira.demo.example/browse/INC-100044', now() - make_interval(mins => 34619), NULL),
    ('INC-100045', 'YAPE', 23, 'Media', 'monitoreo', 'Alertas no emitidas para Pagos de billetera · Operaciones (perfil-10)', 'El servicio Pagos de billetera · Operaciones (perfil-10) (POST /perfil-10/v1/pagos) tuvo errores visibles en los logs durante 20 minutos, pero no se emitió ninguna alerta al equipo de soporte.', 'Sin eventos de alerta durante 20 min con errores 5xx en los logs | POST /perfil-10/v1/pagos', 'La regla de alerta apuntaba a un identificador de servicio antiguo.', 'Se corrige la regla de alerta y se agrega una prueba mensual de las notificaciones.', 'Soporte ITSM', 'Terminado', 'https://jira.demo.example/browse/INC-100045', now() - make_interval(mins => 79388), now() - make_interval(mins => 78169)),
    ('INC-100046', 'YAPE', 23, 'Media', 'latencia_timeout', 'Alta latencia y timeouts en Pagos de billetera · Operaciones (perfil-10)', 'Los canales reportan lentitud en Pagos de billetera · Operaciones (perfil-10) (POST /perfil-10/v1/pagos). La latencia p95 llega a 2526 ms durante 120 minutos y se acumulan 253 solicitudes con timeout.', 'p95=2526 ms | timeouts=253 en 120 min | POST /perfil-10/v1/pagos', NULL, NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100046', now() - make_interval(mins => 106950), NULL),
    ('INC-100047', 'MBBK', 24, 'Alta', 'certificado_vencido', 'Certificado TLS vencido en Saldos de cuentas · Web (perfil-02)', 'Las llamadas a Saldos de cuentas · Web (perfil-02) (GET /perfil-02/v1/saldos/{cuentaId}) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', 'PKIX path validation failed: certificate expired | 17.7% de solicitudes fallidas', NULL, NULL, 'Seguridad', 'En Procesado', 'https://jira.demo.example/browse/INC-100047', now() - make_interval(mins => 89056), NULL),
    ('INC-100048', 'MBBK', 24, 'Media', 'error_http_5xx', 'Error HTTP 500 en Saldos de cuentas · Web (perfil-02)', 'Los consumidores de Saldos de cuentas · Web (perfil-02) (GET /perfil-02/v1/saldos/{cuentaId}) reciben HTTP 500 de forma intermitente en producción. Se registran 767 errores en 15 minutos y el 21.6% de las solicitudes falla.', 'NullPointerException en el mapeador de respuesta | GET /perfil-02/v1/saldos/{cuentaId} | HTTP 500 | 21.6% de solicitudes', 'Una excepción no controlada en el controlador tras el último cambio de código.', 'Se agrega el manejo de la excepción y una respuesta de error controlada. Se incorpora una prueba que reproduce el caso.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100048', now() - make_interval(mins => 25059), now() - make_interval(mins => 24896)),
    ('INC-100049', 'MBBK', 25, 'Alta', 'cpu_bd', 'Alto consumo de CPU en la base de datos de Saldos de cuentas · Móvil (perfil-03)', 'La base de datos de Saldos de cuentas · Móvil (perfil-03) (MBBK) sostiene 28.4% de CPU durante 60 minutos. Las solicitudes a GET /perfil-03/v1/saldos/{cuentaId} aumentan su tiempo de respuesta.', 'CPU 28.4% durante 60 min | consulta de 315 s sin índice', NULL, NULL, 'Base de Datos', 'En Procesado', 'https://jira.demo.example/browse/INC-100049', now() - make_interval(mins => 58064), NULL),
    ('INC-100050', 'MBBK', 25, 'Media', 'monitoreo', 'Alertas no emitidas para Saldos de cuentas · Móvil (perfil-03)', 'El servicio Saldos de cuentas · Móvil (perfil-03) (GET /perfil-03/v1/saldos/{cuentaId}) tuvo errores visibles en los logs durante 20 minutos, pero no se emitió ninguna alerta al equipo de soporte.', 'La regla de alerta no se evaluó | canal de notificación sin respuesta', 'Hipótesis: la regla de alerta apuntaba a un identificador de servicio antiguo.', NULL, 'Soporte ITSM', 'En Procesado', 'https://jira.demo.example/browse/INC-100050', now() - make_interval(mins => 37063), NULL),
    ('INC-100051', 'MBBK', 26, 'Crítica', 'certificado_vencido', 'Certificado TLS vencido en Saldos de cuentas · Conciliación (perfil-04)', 'Las llamadas a Saldos de cuentas · Conciliación (perfil-04) (GET /perfil-04/v1/saldos/{cuentaId}) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', 'PKIX path validation failed: certificate expired | 37.1% de solicitudes fallidas', 'El certificado no se renovó a tiempo y no había alerta de vencimiento.', 'Se renueva el certificado y se agrega una alerta 30 días antes del vencimiento.', 'Seguridad', 'Terminado', 'https://jira.demo.example/browse/INC-100051', now() - make_interval(mins => 120742), now() - make_interval(mins => 120720)),
    ('INC-100052', 'MBBK', 26, 'Alta', 'latencia_timeout', 'Alta latencia y timeouts en Saldos de cuentas · Conciliación (perfil-04)', 'El servicio Saldos de cuentas · Conciliación (perfil-04) (GET /perfil-04/v1/saldos/{cuentaId}) de MBBK responde con un percentil 95 de 4120 ms (umbral de 800 ms) y el 11.8% de las solicitudes termina en timeout.', 'ReadTimeoutException tras 10 s llamando a una dependencia interna | GET /perfil-04/v1/saldos/{cuentaId}', 'Una dependencia interna respondía lento y no había un tiempo máximo configurado.', 'Se define un tiempo máximo de 3 s con reintentos y espera exponencial hacia la dependencia.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100052', now() - make_interval(mins => 41861), now() - make_interval(mins => 41816)),
    ('INC-100053', 'MBBK', 27, 'Alta', 'conexiones_bd', 'Pool de conexiones agotado en Saldos de cuentas · Backoffice (perfil-05)', 'El servicio Saldos de cuentas · Backoffice (perfil-05) (GET /perfil-05/v1/saldos/{cuentaId}) de MBBK devuelve errores porque todas las conexiones a la base de datos están ocupadas. El 4.4% de las solicitudes falla en horas pico.', '462 conexiones activas de 242 permitidas | 4.4% de solicitudes con error', 'Conexiones que no se liberaban por un error en el manejo de transacciones.', 'Se amplía el pool de conexiones y se define un tiempo máximo de uso por conexión.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100053', now() - make_interval(mins => 95442), now() - make_interval(mins => 95233)),
    ('INC-100054', 'MBBK', 27, 'Alta', 'latencia_timeout', 'Alta latencia y timeouts en Saldos de cuentas · Backoffice (perfil-05)', 'El servicio Saldos de cuentas · Backoffice (perfil-05) (GET /perfil-05/v1/saldos/{cuentaId}) de MBBK responde con un percentil 95 de 4523 ms (umbral de 800 ms) y el 31.1% de las solicitudes termina en timeout.', 'ReadTimeoutException tras 10 s llamando a una dependencia interna | GET /perfil-05/v1/saldos/{cuentaId}', 'Consultas sin índice a la base de datos aumentaban el tiempo de respuesta.', 'Se limita la tasa de reintentos y se amplía el pool de hilos del servicio.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100054', now() - make_interval(mins => 115473), now() - make_interval(mins => 115407)),
    ('INC-100055', 'MBBK', 28, 'Media', 'latencia_timeout', 'Alta latencia y timeouts en Saldos de cuentas · Monitoreo (perfil-06)', 'Los canales reportan lentitud en Saldos de cuentas · Monitoreo (perfil-06) (GET /perfil-06/v1/saldos/{cuentaId}). La latencia p95 llega a 5385 ms durante 20 minutos y se acumulan 111 solicitudes con timeout.', 'Latencia p95 de 5385 ms sostenida durante 20 min | GET /perfil-06/v1/saldos/{cuentaId}', 'Hipótesis: el pool de hilos del servicio estaba saturado por reintentos de los consumidores.', NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100055', now() - make_interval(mins => 58233), NULL),
    ('INC-100056', 'MBBK', 28, 'Crítica', 'memoria_bd', 'Alto consumo de memoria en la base de datos de Saldos de cuentas · Monitoreo (perfil-06)', 'La base de datos que soporta Saldos de cuentas · Monitoreo (perfil-06) (MBBK) llega al 22.9% de memoria. El servicio (GET /perfil-06/v1/saldos/{cuentaId}) se degrada y podría fallar por falta de recursos si continúa.', 'work_mem excedido | archivos temporales de 355 MB | memoria 22.9%', 'Un exceso de conexiones abiertas inflaba el uso de memoria del servidor.', 'Se reduce el límite de conexiones, se cierran las sesiones inactivas y se ajusta el pool del servicio.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100056', now() - make_interval(mins => 65257), now() - make_interval(mins => 65153)),
    ('INC-100057', 'MBBK', 29, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Saldos de cuentas · Integración (perfil-07)', 'El servicio Saldos de cuentas · Integración (perfil-07) (GET /perfil-07/v1/saldos/{cuentaId}) falla al invocar la transacción del mainframe. El 28.6% de las solicitudes termina en error o timeout.', 'Respuesta vacía del mainframe | 785 solicitudes afectadas en 45 min', 'La cola de transacciones del mainframe estaba saturada por un proceso batch.', 'Se coordina el calendario de mantenimientos y se agrega un mensaje de contingencia en el servicio.', 'Soporte Mainframe', 'Terminado', 'https://jira.demo.example/browse/INC-100057', now() - make_interval(mins => 71380), now() - make_interval(mins => 70502)),
    ('INC-100058', 'MBBK', 29, 'Crítica', 'error_http_5xx', 'Error HTTP 500 en Saldos de cuentas · Integración (perfil-07)', 'El servicio Saldos de cuentas · Integración (perfil-07) (GET /perfil-07/v1/saldos/{cuentaId}) de MBBK responde HTTP 500 en producción. El 29.7% de las solicitudes de los últimos 120 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'Unhandled exception en el controlador del servicio | GET /perfil-07/v1/saldos/{cuentaId} | HTTP 500 | 184 errores en 120 min', NULL, NULL, 'AgileOPS', 'Registrado', 'https://jira.demo.example/browse/INC-100058', now() - make_interval(mins => 125393), NULL),
    ('INC-100059', 'MBBK', 30, 'Media', 'autenticacion', 'Errores 401 y 403 en Saldos de cuentas · Regresión (perfil-08)', 'Los consumidores de Saldos de cuentas · Regresión (perfil-08) (GET /perfil-08/v1/saldos/{cuentaId}) reciben HTTP 401 y 403 en producción. El 32.5% de las solicitudes es rechazado por autenticación.', 'HTTP 401 invalid_token | GET /perfil-08/v1/saldos/{cuentaId} | 32.5% de solicitudes', NULL, NULL, 'Control de Accesos', 'Registrado', 'https://jira.demo.example/browse/INC-100059', now() - make_interval(mins => 35269), NULL),
    ('INC-100060', 'MBBK', 30, 'Media', 'latencia_timeout', 'Alta latencia y timeouts en Saldos de cuentas · Regresión (perfil-08)', 'El servicio Saldos de cuentas · Regresión (perfil-08) (GET /perfil-08/v1/saldos/{cuentaId}) de MBBK responde con un percentil 95 de 5311 ms (umbral de 800 ms) y el 17.4% de las solicitudes termina en timeout.', NULL, 'Una dependencia interna respondía lento y no había un tiempo máximo configurado.', 'Se define un tiempo máximo de 3 s con reintentos y espera exponencial hacia la dependencia.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100060', now() - make_interval(mins => 61817), now() - make_interval(mins => 61022)),
    ('INC-100061', 'MBBK', 31, 'Baja', 'latencia_timeout', 'Alta latencia y timeouts en Saldos de cuentas · Contingencia (perfil-09)', 'El servicio Saldos de cuentas · Contingencia (perfil-09) (GET /perfil-09/v1/saldos/{cuentaId}) de MBBK responde con un percentil 95 de 3729 ms (umbral de 800 ms) y el 36.7% de las solicitudes termina en timeout.', NULL, NULL, NULL, 'AgileOPS', 'Registrado', 'https://jira.demo.example/browse/INC-100061', now() - make_interval(mins => 25392), NULL),
    ('INC-100062', 'MBBK', 31, 'Crítica', 'error_http_5xx', 'Error HTTP 500 en Saldos de cuentas · Contingencia (perfil-09)', 'El servicio Saldos de cuentas · Contingencia (perfil-09) (GET /perfil-09/v1/saldos/{cuentaId}) de MBBK responde HTTP 500 en producción. El 28.1% de las solicitudes de los últimos 15 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'Unhandled exception en el controlador del servicio | GET /perfil-09/v1/saldos/{cuentaId} | HTTP 500 | 240 errores en 15 min', 'Un campo opcional llegaba nulo y no se validaba antes de armar la respuesta.', 'Se validan los campos opcionales antes de armar la respuesta y se devuelve 404 cuando el recurso no existe. Se despliega el parche y se monitorea durante 60 minutos.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100062', now() - make_interval(mins => 56742), now() - make_interval(mins => 56650)),
    ('INC-100063', 'MBBK', 32, 'Alta', 'error_http_5xx', 'Error HTTP 500 en Saldos de cuentas · Operaciones (perfil-10)', 'Los consumidores de Saldos de cuentas · Operaciones (perfil-10) (GET /perfil-10/v1/saldos/{cuentaId}) reciben HTTP 500 de forma intermitente en producción. Se registran 478 errores en 120 minutos y el 20.1% de las solicitudes falla.', 'NullPointerException en el mapeador de respuesta | GET /perfil-10/v1/saldos/{cuentaId} | HTTP 500 | 20.1% de solicitudes', 'Hipótesis: un dato con formato inesperado rompía la serialización de la respuesta.', NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100063', now() - make_interval(mins => 70367), NULL),
    ('INC-100064', 'MBBK', 32, 'Crítica', 'conexiones_bd', 'Pool de conexiones agotado en Saldos de cuentas · Operaciones (perfil-10)', 'El servicio Saldos de cuentas · Operaciones (perfil-10) (GET /perfil-10/v1/saldos/{cuentaId}) de MBBK devuelve errores porque todas las conexiones a la base de datos están ocupadas. El 37.4% de las solicitudes falla en horas pico.', 'Connection is not available, request timed out after 30000ms | GET /perfil-10/v1/saldos/{cuentaId}', 'Conexiones que no se liberaban por un error en el manejo de transacciones.', 'Se corrige la liberación de conexiones y se agrega una alerta por saturación del pool.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100064', now() - make_interval(mins => 59624), now() - make_interval(mins => 59565)),
    ('INC-100065', 'TTIB', 33, 'Media', 'memoria_bd', 'Alto consumo de memoria en la base de datos de Transferencias interbancarias · Web (perfil-02)', 'La base de datos que soporta Transferencias interbancarias · Web (perfil-02) (TTIB) llega al 10.2% de memoria. El servicio (GET /perfil-02/v1/transferencias/{id}) se degrada y podría fallar por falta de recursos si continúa.', 'work_mem excedido | archivos temporales de 334 MB | memoria 10.2%', 'Un exceso de conexiones abiertas inflaba el uso de memoria del servidor.', 'Se limita la concurrencia de reportes y se mueven a la réplica de lectura.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100065', now() - make_interval(mins => 1355), now() - make_interval(mins => 919)),
    ('INC-100066', 'TTIB', 33, 'Alta', 'certificado_vencido', 'Certificado TLS vencido en Transferencias interbancarias · Web (perfil-02)', 'Las llamadas a Transferencias interbancarias · Web (perfil-02) (GET /perfil-02/v1/transferencias/{id}) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', 'SSLHandshakeException: certificate expired | GET /perfil-02/v1/transferencias/{id}', 'El certificado no se renovó a tiempo y no había alerta de vencimiento.', 'Se renueva el certificado y se agrega una alerta 30 días antes del vencimiento.', 'Seguridad', 'Terminado', 'https://jira.demo.example/browse/INC-100066', now() - make_interval(mins => 57542), now() - make_interval(mins => 57251)),
    ('INC-100067', 'TTIB', 34, 'Alta', 'memoria_bd', 'Alto consumo de memoria en la base de datos de Transferencias interbancarias · Web (perfil-02)', 'La base de datos que soporta Transferencias interbancarias · Web (perfil-02) (TTIB) llega al 33.7% de memoria. El servicio (POST /perfil-02/v1/transferencias) se degrada y podría fallar por falta de recursos si continúa.', 'Memoria 33.7% durante 15 min | 293 conexiones activas de 500', 'Reportes simultáneos creaban tablas temporales grandes.', 'Se reescribe la consulta con filtros por fecha y paginación.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100067', now() - make_interval(mins => 106502), now() - make_interval(mins => 106428)),
    ('INC-100068', 'TTIB', 34, 'Crítica', 'error_http_5xx', 'Error HTTP 500 en Transferencias interbancarias · Web (perfil-02)', 'El servicio Transferencias interbancarias · Web (perfil-02) (POST /perfil-02/v1/transferencias) de TTIB responde HTTP 500 en producción. El 33.0% de las solicitudes de los últimos 60 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'HTTP 500 sostenido en POST /perfil-02/v1/transferencias | pico de 429 errores por minuto', NULL, NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100068', now() - make_interval(mins => 40105), NULL),
    ('INC-100069', 'TTIB', 35, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Transferencias interbancarias · Móvil (perfil-03)', 'El servicio Transferencias interbancarias · Móvil (perfil-03) (GET /perfil-03/v1/transferencias/{id}) falla al invocar la transacción del mainframe. El 25.7% de las solicitudes termina en error o timeout.', 'Respuesta vacía del mainframe | 655 solicitudes afectadas en 20 min', 'Hipótesis: la cola de transacciones del mainframe estaba saturada por un proceso batch.', NULL, 'Soporte Mainframe', 'En Procesado', 'https://jira.demo.example/browse/INC-100069', now() - make_interval(mins => 85564), NULL),
    ('INC-100070', 'TTIB', 35, 'Alta', 'conexiones_bd', 'Pool de conexiones agotado en Transferencias interbancarias · Móvil (perfil-03)', 'El servicio Transferencias interbancarias · Móvil (perfil-03) (GET /perfil-03/v1/transferencias/{id}) de TTIB devuelve errores porque todas las conexiones a la base de datos están ocupadas. El 15.3% de las solicitudes falla en horas pico.', 'Connection is not available, request timed out after 30000ms | GET /perfil-03/v1/transferencias/{id}', NULL, NULL, 'Base de Datos', 'Registrado', 'https://jira.demo.example/browse/INC-100070', now() - make_interval(mins => 42368), NULL),
    ('INC-100071', 'TTIB', 36, 'Alta', 'autenticacion', 'Errores 401 y 403 en Transferencias interbancarias · Móvil (perfil-03)', 'Los consumidores de Transferencias interbancarias · Móvil (perfil-03) (POST /perfil-03/v1/transferencias) reciben HTTP 401 y 403 en producción. El 30.2% de las solicitudes es rechazado por autenticación.', 'HTTP 403 perfil de consumo sin permiso | POST /perfil-03/v1/transferencias | 643 rechazos en 120 min', 'El perfil de consumo del canal fue revocado por error durante una limpieza de accesos.', 'Se agrega un margen de tolerancia de 30 segundos en la validación de expiración del token.', 'Control de Accesos', 'Terminado', 'https://jira.demo.example/browse/INC-100071', now() - make_interval(mins => 128037), now() - make_interval(mins => 127949)),
    ('INC-100072', 'TTIB', 36, 'Alta', 'latencia_timeout', 'Alta latencia y timeouts en Transferencias interbancarias · Móvil (perfil-03)', 'Los canales reportan lentitud en Transferencias interbancarias · Móvil (perfil-03) (POST /perfil-03/v1/transferencias). La latencia p95 llega a 3576 ms durante 45 minutos y se acumulan 458 solicitudes con timeout.', 'ReadTimeoutException tras 10 s llamando a una dependencia interna | POST /perfil-03/v1/transferencias', 'Hipótesis: el pool de hilos del servicio estaba saturado por reintentos de los consumidores.', NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100072', now() - make_interval(mins => 74177), NULL),
    ('INC-100073', 'TTIB', 37, 'Crítica', 'error_http_5xx', 'Error HTTP 500 en Transferencias interbancarias · Conciliación (perfil-04)', 'El servicio Transferencias interbancarias · Conciliación (perfil-04) (GET /perfil-04/v1/transferencias/{id}) de TTIB responde HTTP 500 en producción. El 32.9% de las solicitudes de los últimos 15 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'HTTP 500 sostenido en GET /perfil-04/v1/transferencias/{id} | pico de 545 errores por minuto', 'Un campo opcional llegaba nulo y no se validaba antes de armar la respuesta.', 'Se corrige la serialización y se agrega validación de formato en la entrada del servicio.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100073', now() - make_interval(mins => 44831), now() - make_interval(mins => 44797)),
    ('INC-100074', 'TTIB', 37, 'Media', 'latencia_timeout', 'Alta latencia y timeouts en Transferencias interbancarias · Conciliación (perfil-04)', 'El servicio Transferencias interbancarias · Conciliación (perfil-04) (GET /perfil-04/v1/transferencias/{id}) de TTIB responde con un percentil 95 de 1738 ms (umbral de 800 ms) y el 16.4% de las solicitudes termina en timeout.', 'Latencia p95 de 1738 ms sostenida durante 30 min | GET /perfil-04/v1/transferencias/{id}', 'El pool de hilos del servicio estaba saturado por reintentos de los consumidores.', 'Se crea el índice faltante y se reescribe la consulta con filtros por fecha.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100074', now() - make_interval(mins => 90969), now() - make_interval(mins => 90752)),
    ('INC-100075', 'TTIB', 38, 'Media', 'integracion_mainframe', 'Fallas de integración con el mainframe en Transferencias interbancarias · Conciliación (perfil-04)', 'El servicio Transferencias interbancarias · Conciliación (perfil-04) (POST /perfil-04/v1/transferencias) falla al invocar la transacción del mainframe. El 21.4% de las solicitudes termina en error o timeout.', 'Respuesta vacía del mainframe | 679 solicitudes afectadas en 90 min', 'La cola de transacciones del mainframe estaba saturada por un proceso batch.', 'Se coordina el calendario de mantenimientos y se agrega un mensaje de contingencia en el servicio.', 'Soporte Mainframe', 'Terminado', 'https://jira.demo.example/browse/INC-100075', now() - make_interval(mins => 67503), now() - make_interval(mins => 67257)),
    ('INC-100076', 'TTIB', 38, 'Alta', 'conexiones_bd', 'Pool de conexiones agotado en Transferencias interbancarias · Conciliación (perfil-04)', 'El servicio Transferencias interbancarias · Conciliación (perfil-04) (POST /perfil-04/v1/transferencias) de TTIB devuelve errores porque todas las conexiones a la base de datos están ocupadas. El 36.3% de las solicitudes falla en horas pico.', '660 conexiones activas de 327 permitidas | 36.3% de solicitudes con error', 'El pool de conexiones era demasiado pequeño para el volumen de la hora pico.', 'Se corrige la liberación de conexiones y se agrega una alerta por saturación del pool.', 'Base de Datos', 'Terminado', 'https://jira.demo.example/browse/INC-100076', now() - make_interval(mins => 56416), now() - make_interval(mins => 56325)),
    ('INC-100077', 'TTIB', 39, 'Alta', 'certificado_vencido', 'Certificado TLS vencido en Transferencias interbancarias · Backoffice (perfil-05)', 'Las llamadas a Transferencias interbancarias · Backoffice (perfil-05) (GET /perfil-05/v1/transferencias/{id}) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', 'SSLHandshakeException: certificate expired | GET /perfil-05/v1/transferencias/{id}', 'El certificado no se renovó a tiempo y no había alerta de vencimiento.', 'Se renueva el certificado y se agrega una alerta 30 días antes del vencimiento.', 'Seguridad', 'Terminado', 'https://jira.demo.example/browse/INC-100077', now() - make_interval(mins => 40958), now() - make_interval(mins => 40866)),
    ('INC-100078', 'TTIB', 39, 'Media', 'latencia_timeout', 'Alta latencia y timeouts en Transferencias interbancarias · Backoffice (perfil-05)', 'Los canales reportan lentitud en Transferencias interbancarias · Backoffice (perfil-05) (GET /perfil-05/v1/transferencias/{id}). La latencia p95 llega a 2661 ms durante 60 minutos y se acumulan 287 solicitudes con timeout.', 'ReadTimeoutException tras 10 s llamando a una dependencia interna | GET /perfil-05/v1/transferencias/{id}', 'Hipótesis: consultas sin índice a la base de datos aumentaban el tiempo de respuesta.', NULL, 'AgileOPS', 'En Procesado', 'https://jira.demo.example/browse/INC-100078', now() - make_interval(mins => 91449), NULL),
    ('INC-100079', 'TTIB', 40, 'Crítica', 'error_http_5xx', 'Error HTTP 500 en Transferencias interbancarias · Backoffice (perfil-05)', 'El servicio Transferencias interbancarias · Backoffice (perfil-05) (POST /perfil-05/v1/transferencias) de TTIB responde HTTP 500 en producción. El 8.6% de las solicitudes de los últimos 45 minutos termina en error y el canal consumidor reporta fallos en sus operaciones.', 'NullPointerException en el mapeador de respuesta | POST /perfil-05/v1/transferencias | HTTP 500 | 8.6% de solicitudes', 'Una excepción no controlada en el controlador tras el último cambio de código.', 'Se agrega el manejo de la excepción y una respuesta de error controlada. Se incorpora una prueba que reproduce el caso.', 'AgileOPS', 'Terminado', 'https://jira.demo.example/browse/INC-100079', now() - make_interval(mins => 28081), now() - make_interval(mins => 27974)),
    ('INC-100080', 'TTIB', 40, 'Crítica', 'certificado_vencido', 'Certificado TLS vencido en Transferencias interbancarias · Backoffice (perfil-05)', 'Las llamadas a Transferencias interbancarias · Backoffice (perfil-05) (POST /perfil-05/v1/transferencias) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', 'PKIX path validation failed: certificate expired | 34.3% de solicitudes fallidas', NULL, NULL, 'Seguridad', 'Registrado', 'https://jira.demo.example/browse/INC-100080', now() - make_interval(mins => 37030), NULL),
    ('INC-100081', 'TTIB', 41, 'Crítica', 'certificado_vencido', 'Certificado TLS vencido en Transferencias interbancarias · Monitoreo (perfil-06)', 'Las llamadas a Transferencias interbancarias · Monitoreo (perfil-06) (GET /perfil-06/v1/transferencias/{id}) fallan en producción porque el certificado TLS venció. Los consumidores reciben errores de conexión segura.', 'SSLHandshakeException: certificate expired | GET /perfil-06/v1/transferencias/{id}', 'El certificado no se renovó a tiempo y no había alerta de vencimiento.', 'Se renueva el certificado y se agrega una alerta 30 días antes del vencimiento.', 'Seguridad', 'Terminado', 'https://jira.demo.example/browse/INC-100081', now() - make_interval(mins => 11656), now() - make_interval(mins => 11558)),
    ('INC-100082', 'TTIB', 41, 'Media', 'autenticacion', 'Errores 401 y 403 en Transferencias interbancarias · Monitoreo (perfil-06)', 'Los consumidores de Transferencias interbancarias · Monitoreo (perfil-06) (GET /perfil-06/v1/transferencias/{id}) reciben HTTP 401 y 403 en producción. El 2.5% de las solicitudes es rechazado por autenticación.', NULL, 'Los tokens se validaban con una diferencia de relojes entre servidores.', 'Se agrega un margen de tolerancia de 30 segundos en la validación de expiración del token.', 'Control de Accesos', 'Terminado', 'https://jira.demo.example/browse/INC-100082', now() - make_interval(mins => 66093), now() - make_interval(mins => 64704)),
