    ('INC-100196', 'MBBK', 98, 'Media', 'memoria_bd', 'Alto consumo de memoria en la base de datos de Saldos de cuentas · Web (perfil-02) · Validación de contingencia', 'La base de datos que soporta Saldos de cuentas · Web (perfil-02) · Validación de contingencia (MBBK) llega al 10.9% de memoria. El servicio (GET /contingencia/perfil-02/v1/saldos/{cuentaId}) se degrada y podría fallar por falta de recursos si continúa.', 'work_mem excedido | archivos temporales de 233 MB | memoria 10.9%', NULL, NULL, 'Base de Datos', 'Registrado', 'https://jira.demo.example/browse/INC-100196', now() - make_interval(mins => 57195), NULL),
